/// <summary>
/// PricingAttribute of table <c>SalesTable</c> field SourceDocumentHeader.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesTable, GUPPricingAttributeSourceLevel::Header)]
internal class GUPPricingAttributeSalesTableSourceDocumentHeader extends GUPPricingAttributeSalesTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesTable, SourceDocumentHeader);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Integer);
    SalesTable salesTable;
    while select SourceDocumentHeader from salesTable
        group by SourceDocumentHeader
    {
        ret.add(salesTable.SourceDocumentHeader);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesTable, SourceDocumentHeader));
    qbr.value(queryValue(_value));
}
